import{_ as a,o,c as t,a8 as l}from"./chunks/framework.BppdKxCY.js";const g=JSON.parse('{"title":"EP.69 让 Google 搜到你的站","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.69-nextjs-google-seo.md","filePath":"comics/EP.69-nextjs-google-seo.md","lastUpdated":1793706365000}'),i={name:"comics/EP.69-nextjs-google-seo.md"};function s(r,e,n,d,c,S){return o(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="ep-69-让-google-搜到你的站" tabindex="-1">EP.69 让 Google 搜到你的站 <a class="header-anchor" href="#ep-69-让-google-搜到你的站" aria-label="Permalink to &quot;EP.69 让 Google 搜到你的站&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../95-nextjs-google-seo">95-nextjs-google-seo.md</a>（95.1 渲染策略 / 95.2 Metadata / 95.3 sitemap+JSON-LD / 95.4 CWV）· 示例：<code>examples/95-01-nextjs-google-seo.ts</code></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ul><li><strong>第 1 格</strong>：海外站点 Google 搜不到——CSR 渲染爬虫拿不到内容。</li><li><strong>第 2 格</strong>：码叔揭秘渲染策略与 Metadata——SEO 页面用 SSG/SSR/ISR，写对 title/description/OG。</li><li><strong>第 3 格</strong>：像素酱实证 sitemap + JSON-LD——让爬虫发现并理解页面。</li><li><strong>第 4 格</strong>：码叔结案——Core Web Vitals 达标直接影响搜索排名。</li></ul><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第-1-格-·-csr-不利于-seo" tabindex="-1">第 1 格 · CSR 不利于 SEO <a class="header-anchor" href="#第-1-格-·-csr-不利于-seo" aria-label="Permalink to &quot;第 1 格 · CSR 不利于 SEO&quot;">​</a></h3><ul><li>纯客户端渲染的页面，爬虫拿到的是空 HTML；</li><li>Googlebot 虽能执行 JS，但不稳定且慢；</li><li>需要 SEO 的页面必须服务端渲染（SSG/SSR/ISR）。</li></ul><h3 id="第-2-格-·-渲染策略与-metadata" tabindex="-1">第 2 格 · 渲染策略与 Metadata <a class="header-anchor" href="#第-2-格-·-渲染策略与-metadata" aria-label="Permalink to &quot;第 2 格 · 渲染策略与 Metadata&quot;">​</a></h3><ul><li>SSG（构建时）/ SSR（请求时）/ ISR（定时重建）/ CSR（客户端）；</li><li>Metadata：title&lt;60字符，description 50-160字符，OG image 1200×630。</li></ul><h3 id="第-3-格-·-sitemap-与-json-ld" tabindex="-1">第 3 格 · sitemap 与 JSON-LD <a class="header-anchor" href="#第-3-格-·-sitemap-与-json-ld" aria-label="Permalink to &quot;第 3 格 · sitemap 与 JSON-LD&quot;">​</a></h3><ul><li><code>sitemap.xml</code> 列出所有 URL，<code>robots.txt</code> 指向它；</li><li>JSON-LD 结构化数据（Article/Product/FAQPage）让搜索结果展示富片段。</li></ul><h3 id="第-4-格-·-core-web-vitals" tabindex="-1">第 4 格 · Core Web Vitals <a class="header-anchor" href="#第-4-格-·-core-web-vitals" aria-label="Permalink to &quot;第 4 格 · Core Web Vitals&quot;">​</a></h3><ul><li>LCP&lt;2.5s、CLS&lt;0.1、INP&lt;200ms 为 Good；</li><li>三项直接影响 Google 搜索排名。</li></ul><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><blockquote><p>🔗 正文对照：<a href="./../95-nextjs-google-seo#_95-7-本章避坑清单">《95.7 本章避坑清单》</a></p></blockquote><ol><li>用 CSR 做 SEO 页面 → 用 SSG/SSR/ISR；</li><li>title 超 60 字符被截断 → 控制长度；</li><li>图片加载后布局跳动（CLS）→ 固定宽高。</li></ol><h2 id="自测-3-题-含答案" tabindex="-1">自测 3 题（含答案） <a class="header-anchor" href="#自测-3-题-含答案" aria-label="Permalink to &quot;自测 3 题（含答案）&quot;">​</a></h2><ol><li>需要 SEO 的页面该用哪种渲染策略？——<strong>SSG/SSR/ISR，不能用纯 CSR</strong>。</li><li>JSON-LD 结构化数据有什么用？——<strong>让 Google 理解页面语义，搜索结果展示富片段（FAQ、评分等）</strong>。</li><li>Core Web Vitals 三个指标的 Good 阈值？——<strong>LCP&lt;2.5s, CLS&lt;0.1, INP&lt;200ms</strong>。</li></ol>',18)])])}const u=a(i,[["render",s]]);export{g as __pageData,u as default};
